package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import java.util.*;import java.util.concurrent.*;import java.security.*;import java.time.*;
/** Browser authorization is separate from the private, one-use app polling secret. No bearer tokens in URLs. */
@RestController @RequestMapping("/api/auth/social") public class SocialLoginController {
 private final SocialOAuthGateway gateway;private final SocialIdentityRepository identities;private final AccountRepository accounts;private final AuthTokenRepository tokens;private final AccountViews views;private final SecureRandom random=new SecureRandom();private final ConcurrentHashMap<String,Flow> flows=new ConcurrentHashMap<>();
 static class Flow {final String provider,poll;final Role role;final Instant until=Instant.now().plusSeconds(300);Long accountId;String failure;boolean callbackUsed,consumed;Flow(String provider,String poll,Role role){this.provider=provider;this.poll=poll;this.role=role;}}
 public SocialLoginController(SocialOAuthGateway gateway,SocialIdentityRepository identities,AccountRepository accounts,AuthTokenRepository tokens,AccountViews views){this.gateway=gateway;this.identities=identities;this.accounts=accounts;this.tokens=tokens;this.views=views;}
 public record Start(String provider,String role){}public record Started(String authorizationUrl,String state,String pollSecret){}public record Poll(String state,String pollSecret){}public record Result(String status,String message,Dto.LoginResponse login){}
 private String secret(){byte[] bytes=new byte[32];random.nextBytes(bytes);return HexFormat.of().formatHex(bytes);}
 static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 @GetMapping("/providers") public Map<String,Boolean> providers(){return Map.of("google",gateway.configured("google"),"kakao",gateway.configured("kakao"));}
 @PostMapping("/start") public Started start(@RequestBody Start r){Role role=AuthController.role(r.role());if(!gateway.configured(r.provider()))throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"간편 로그인 서비스 연결이 필요해요. 아이디 로그인으로 이용해주세요");flows.entrySet().removeIf(e->e.getValue().until.isBefore(Instant.now()));if(flows.size()>=1000)throw new ApiException(HttpStatus.TOO_MANY_REQUESTS,"잠시 후 다시 로그인해주세요");String state=secret(),poll=secret();flows.put(state,new Flow(r.provider(),hash(poll),role));return new Started(gateway.authorize(r.provider(),state),state,poll);}
 @GetMapping(value="/{provider}/callback",produces=MediaType.TEXT_HTML_VALUE) @Transactional public String callback(@PathVariable String provider,@RequestParam String state,@RequestParam(required=false)String code,@RequestParam(required=false)String error){Flow f=flows.get(state);if(f==null||!f.provider.equals(provider)||f.until.isBefore(Instant.now()))throw new ApiException(HttpStatus.BAD_REQUEST,"로그인 요청이 만료됐어요. 앱에서 다시 시작해주세요");synchronized(f){if(f.callbackUsed)throw new ApiException(HttpStatus.CONFLICT,"이미 처리한 로그인 요청이에요");f.callbackUsed=true;if(error!=null||code==null||code.isBlank()){f.failure="로그인이 취소됐어요";return page(false);}try{var user=gateway.exchange(provider,code);String identity=provider+":"+hash(user.subject());Account account=identities.findById(identity).map(SocialIdentity::getAccount).orElse(null);if(account==null){String username=provider.substring(0,1)+hash(user.subject()).substring(0,24);if(accounts.existsByUsername(username))throw new IllegalStateException("Username conflict");account=accounts.save(new Account(username,new BCryptPasswordEncoder().encode(secret()),f.role,user.name(),""));identities.save(new SocialIdentity(identity,account));}if(account.getRole()!=f.role){f.failure="처음 가입한 사장님·직원 유형을 선택해주세요";return page(false);}f.accountId=account.getId();return page(true);}catch(Exception e){f.failure="간편 로그인을 완료하지 못했어요. 앱에서 다시 시도해주세요";return page(false);}}}
 private String page(boolean success){return "<!doctype html><html lang=\"ko\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>StoreMate 로그인</title><body style=\"font-family:sans-serif;padding:32px\"><h2>"+(success?"로그인이 완료됐어요":"로그인을 완료하지 못했어요")+"</h2><p>StoreMate 앱으로 돌아가주세요.</p></body></html>";}
 @PostMapping("/result") @Transactional public Result result(@RequestBody Poll r){Flow f=flows.get(r.state()==null?"":r.state());if(f==null||r.pollSecret()==null||!r.pollSecret().matches("[a-f0-9]{64}")||!MessageDigest.isEqual(f.poll.getBytes(java.nio.charset.StandardCharsets.US_ASCII),hash(r.pollSecret()).getBytes(java.nio.charset.StandardCharsets.US_ASCII)))throw new ApiException(HttpStatus.BAD_REQUEST,"로그인 요청을 다시 시작해주세요");synchronized(f){if(f.consumed||f.until.isBefore(Instant.now())){flows.remove(r.state(),f);return new Result("expired","로그인 요청이 만료됐어요",null);}if(f.failure!=null){f.consumed=true;return new Result("error",f.failure,null);}if(f.accountId==null)return new Result("pending",null,null);var account=accounts.findById(f.accountId).orElseThrow();String token=secret();tokens.save(new AuthToken(token,account));f.consumed=true;return new Result("complete",null,new Dto.LoginResponse(token,views.of(account)));}}
}
